use crate::resources::{BaseResource, ConnectionPoint, ConnectionSites};
use crate::structural_material::StructuralMaterial;
use serde::{Deserialize, Serialize};
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub struct Placement{pub x:f64,pub y:f64,pub rotation_radians:f64}
#[derive(Serialize,Clone,Debug,PartialEq)]pub struct StructuralUnit{pub material:StructuralMaterial,pub placement:Placement}
impl StructuralUnit{pub fn new(resource_name:impl Into<String>,placement:Placement)->Self{Self{material:StructuralMaterial::single(resource_name),placement}}pub fn from_material(material:crate::resources::Material,placement:Placement)->Option<Self>{Some(Self{material:StructuralMaterial::from_material(material)?,placement})}pub fn resource_name(&self)->Option<&str>{let[(name,amount)]=self.material.constituents()else{return None};if self.material.internal_bonds().is_empty()&&(*amount-1.0).abs()<=f64::EPSILON{Some(name.as_str())}else{None}}pub fn properties(&self,catalog:&[BaseResource])->Option<crate::resources::ResourceProperties>{if !self.material.is_valid()||!self.material.resolves_in_catalog(catalog){return None}Some(self.material.weighted_properties(catalog))}pub fn connection_sites(&self,catalog:&[BaseResource])->Option<ConnectionSites>{self.material.connection_sites(catalog)}pub fn shape<'a>(&self,catalog:&'a [BaseResource])->Option<&'a crate::resources::Shape>{self.material.shape(catalog)}}
impl<'de>Deserialize<'de>for StructuralUnit{fn deserialize<D>(deserializer:D)->Result<Self,D::Error>where D:serde::Deserializer<'de>{#[derive(Deserialize)]struct Stored{material:Option<StructuralMaterial>,resource_name:Option<String>,placement:Placement}let s=Stored::deserialize(deserializer)?;let m=match s.material{Some(m)=>m,None=>StructuralMaterial::single(s.resource_name.ok_or_else(||serde::de::Error::custom("structural unit has no material"))?)};if !m.is_valid(){return Err(serde::de::Error::custom("invalid structural material"))}Ok(Self{material:m,placement:s.placement})}}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq,Eq,Hash)]pub struct ConnectionSiteRef{pub unit_index:usize,pub point_index:usize}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub struct Bond{pub unit_a:usize,pub point_a:usize,pub unit_b:usize,pub point_b:usize,pub strength:f64,pub bond_energy:f64}
impl Bond{pub fn touches(&self,u:usize,p:usize)->bool{(self.unit_a==u&&self.point_a==p)||(self.unit_b==u&&self.point_b==p)}pub fn has_same_identity(&self,o:&Bond)->bool{(self.unit_a==o.unit_a&&self.point_a==o.point_a&&self.unit_b==o.unit_b&&self.point_b==o.point_b)||(self.unit_a==o.unit_b&&self.point_a==o.point_b&&self.unit_b==o.unit_a&&self.point_b==o.point_a)}pub fn is_valid(&self,n:usize,count:impl Fn(usize)->Option<usize>)->bool{if self.unit_a>=n||self.unit_b>=n||!self.bond_energy.is_finite()||self.bond_energy<=f64::EPSILON{return false}match(count(self.unit_a),count(self.unit_b)){(Some(a),Some(b))=>self.point_a<a&&self.point_b<b,_=>false}}}
#[derive(Serialize,Deserialize,Clone,Debug,Default)]pub struct OrganismStructure{pub units:Vec<StructuralUnit>,pub bonds:Vec<Bond>}
impl OrganismStructure{pub fn new()->Self{Self::default()}pub fn add_unit(&mut self,u:StructuralUnit)->usize{self.units.push(u);self.units.len()-1}pub fn add_bond(&mut self,b:Bond)->usize{debug_assert!(b.bond_energy.is_finite()&&b.bond_energy>f64::EPSILON);self.bonds.push(b);self.bonds.len()-1}pub fn is_valid_bond(&self,b:&Bond,c:&[BaseResource])->bool{if !b.is_valid(self.units.len(),|i|self.units.get(i).and_then(|u|u.connection_sites(c)).and_then(|s|match s{ConnectionSites::Corners(p)=>Some(p.len()),_=>None})){return false}let Some(a)=self.units[b.unit_a].properties(c)else{return false};let Some(d)=self.units[b.unit_b].properties(c)else{return false};let strength=crate::combine::bond_strength(a,d);strength.is_finite()&&(0.0..=1.0).contains(&strength)}pub fn connection_site(&self,s:ConnectionSiteRef,c:&[BaseResource])->Option<ConnectionPoint>{match self.units.get(s.unit_index)?.connection_sites(c)?{ConnectionSites::Corners(p)=>p.get(s.point_index).copied(),_=>None}}pub fn available_connection_sites(&self,c:&[BaseResource])->Vec<ConnectionSiteRef>{let mut o=Vec::new();for i in 0..self.units.len(){let Some(ConnectionSites::Corners(p))=self.units[i].connection_sites(c)else{continue};for j in 0..p.len(){if self.connection_count(i,j)==0{o.push(ConnectionSiteRef{unit_index:i,point_index:j})}}}o}pub fn connected_components(&self)->Vec<Vec<usize>>{let mut a=vec![Vec::<usize>::new();self.units.len()];for b in &self.bonds{if b.unit_a<self.units.len()&&b.unit_b<self.units.len(){a[b.unit_a].push(b.unit_b);a[b.unit_b].push(b.unit_a)}}let mut v=vec![false;self.units.len()];let mut out=Vec::new();for st in 0..self.units.len(){if v[st]{continue}let mut q=vec![st];v[st]=true;let mut c=Vec::new();while let Some(u)=q.pop(){c.push(u);for &n in &a[u]{if !v[n]{v[n]=true;q.push(n)}}}c.sort_unstable();out.push(c)}out}pub fn component_connection_sites(&self,c:&[usize],cat:&[BaseResource])->Vec<ConnectionSiteRef>{let set:std::collections::HashSet<usize>=c.iter().copied().collect();self.available_connection_sites(cat).into_iter().filter(|s|set.contains(&s.unit_index)).collect()}pub fn connection_load(&self,u:usize,p:usize,_c:&[BaseResource])->f64{self.bonds.iter().filter(|b|b.touches(u,p)).map(|b|crate::combine::experimental_bond_strength(b.bond_energy)).sum()}pub fn connection_count(&self,u:usize,p:usize)->usize{self.bonds.iter().filter(|b|b.touches(u,p)).count()}pub fn break_bond(&mut self,i:usize)->Option<Bond>{if i<self.bonds.len(){Some(self.bonds.remove(i))}else{None}}pub fn break_matching_bond(&mut self,t:Bond)->Option<Bond>{let i=self.bonds.iter().position(|b|b.has_same_identity(&t))?;self.break_bond(i)}pub fn disconnect_point(&mut self,u:usize,p:usize)->Vec<Bond>{let mut o=Vec::new();let mut i=0;while i<self.bonds.len(){if self.bonds[i].touches(u,p){o.push(self.bonds.remove(i))}else{i+=1}}o}pub fn loaded_points(&self)->Vec<(usize,usize)>{let mut o=Vec::new();for b in &self.bonds{for p in[(b.unit_a,b.point_a),(b.unit_b,b.point_b)]{if !o.contains(&p){o.push(p)}}}o}}
pub fn formation_threshold(a:f64,b:f64,la:f64,lb:f64)->f64{let la=la.max(0.0);let lb=lb.max(0.0);((a+b)/2.0)*(1.0+la.sqrt()+lb.sqrt())}
#[cfg(test)]mod tests{use super::*;#[test]fn material_is_owned_by_unit(){let u=StructuralUnit::new("Carbon",Placement{x:0.0,y:0.0,rotation_radians:0.0});assert_eq!(u.material.constituents(),&[("Carbon".into(),1.0)])}#[test]fn composite_identity_is_preserved(){let m=crate::resources::Material{parts:vec![("Carbon".into(),1.0),("Hydrogen".into(),1.0)],internal_bonds:vec![crate::resources::InternalBond{part_a:0,part_b:1}]};let u=StructuralUnit::from_material(m.clone(),Placement{x:0.0,y:0.0,rotation_radians:0.0}).unwrap();assert_eq!(u.material.material(),&m);assert!(matches!(u.connection_sites(&crate::resources::default_catalog()),Some(ConnectionSites::Corners(_))))}#[test]fn connection_load_tracks_derived_bond_energy_strength(){let catalog=crate::resources::default_catalog();let mut structure=OrganismStructure::new();let a=structure.add_unit(StructuralUnit::new("Carbon",Placement{x:0.0,y:0.0,rotation_radians:0.0}));let b=structure.add_unit(StructuralUnit::new("Carbon",Placement{x:1.0,y:0.0,rotation_radians:0.0}));structure.add_bond(Bond{unit_a:a,point_a:0,unit_b:b,point_b:0,strength:0.05,bond_energy:1.0});let expected=crate::combine::experimental_bond_strength(1.0);assert!((structure.connection_load(a,0,&catalog)-expected).abs()<1e-12);structure.bonds[0].strength=0.95;assert!((structure.connection_load(a,0,&catalog)-expected).abs()<1e-12)}
#[test]fn zero_energy_bonds_are_rejected(){let catalog=crate::resources::default_catalog();let mut structure=OrganismStructure::new();let a=structure.add_unit(StructuralUnit::new("Carbon",Placement{x:0.0,y:0.0,rotation_radians:0.0}));let b=structure.add_unit(StructuralUnit::new("Carbon",Placement{x:1.0,y:0.0,rotation_radians:0.0}));let bond=Bond{unit_a:a,point_a:0,unit_b:b,point_b:0,strength:0.5,bond_energy:0.0};assert!(!structure.is_valid_bond(&bond,&catalog));}
}